INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist Fehlerprotokollierung nur für Entwickler nützlich?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Ops und Support profitieren"}, {"text": "Ja", "correct": false, "because": "Breitere Anwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit Fehlerprotokollierung?', 3, '[{"text": "Fehler nachvollziehbar machen", "correct": true, "because": "Hilft bei Analyse"}, {"text": "Code optimieren", "correct": false, "because": "Sekundäres Ziel"}, {"text": "UI gestalten", "correct": false, "because": "Kein Bezug"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente gehören zur Fehlerprotokollierung?', 5, '[{"text": "Fehlercodes", "correct": true, "because": "Identifizieren Probleme"}, {"text": "Meldungen", "correct": true, "because": "Beschreiben Fehler"}, {"text": "Farbschema", "correct": false, "because": "Irrelevant"}, {"text": "Datenkompression", "correct": false, "because": "Kein Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Fehlercodes sind standardisiert. b) Meldungen sind immer technisch.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) kann nutzerfreundlich sein"}, {"text": "Beides stimmt", "correct": false, "because": "Meldungen variieren"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Fehlerprotokollierung?', 4, '[{"text": "Fehlercodes", "correct": false, "because": "Schlüssel zur Identifikation"}, {"text": "Meldungsdetails", "correct": false, "because": "Erklären Kontext"}, {"text": "Bildauflösung", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Fehlerprotokollierung immer aktiv ist?', 2, '[{"text": "Nein", "correct": true, "because": "Konfigurierbar"}, {"text": "Ja", "correct": false, "because": "Kann deaktiviert werden"}]'),
('00000000-0000-0000-0000-000000000000', 'Welchen Fehlercode wähle ich für "Ungültige Eingabe"?', 3, '[{"text": "400", "correct": true, "because": "Bad Request"}, {"text": "404", "correct": false, "because": "Nicht gefunden"}, {"text": "500", "correct": false, "because": "Serverfehler"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet Fehlerprotokollierung?', 5, '[{"text": "Nachverfolgbarkeit", "correct": true, "because": "Fehler auffindbar"}, {"text": "Support", "correct": true, "because": "Hilft bei Problemlösung"}, {"text": "Schnellere Ausführung", "correct": false, "because": "Kein Effekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Fehlercodes sind optional. b) Meldungen müssen detailliert sein. Stimmt das?', 3, '[{"text": "Nur b) stimmt", "correct": true, "because": "a) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "Codes essenziell"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für Fehlerprotokollierung?', 4, '[{"text": "Log-System", "correct": false, "because": "Speichert Einträge"}, {"text": "Fehlerdetails", "correct": false, "because": "Beschreiben Problem"}, {"text": "Grafikdesign", "correct": true, "because": "Kein Bezug"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind Fehlercodes immer numerisch?', 2, '[{"text": "Nein", "correct": true, "because": "Können alphanumerisch sein"}, {"text": "Ja", "correct": false, "because": "Flexibel definierbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Details gehören in eine Fehlermeldung?', 4, '[{"text": "Beschreibung", "correct": true, "because": "Erklärt Fehler"}, {"text": "Zeitstempel", "correct": true, "because": "Zeigt Wann"}, {"text": "Farbanpassung", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Fehlerprotokollierung Performance senkt. Stimmt das?', 2, '[{"text": "Ja", "correct": true, "because": "Kann Overhead erzeugen"}, {"text": "Nein", "correct": false, "because": "Abhängig von Umsetzung"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Fehlerprotokollierung?', 3, '[{"text": "Klarheit der Meldungen", "correct": true, "because": "Fördert Verständnis"}, {"text": "Schnelle Speicherung", "correct": false, "because": "Qualität zählt"}, {"text": "UI-Optimierung", "correct": false, "because": "Kein Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Fehlerprotokollierung hilft beim Debugging. b) Sie ist nur für Server.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "Auch lokal nutzbar"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Risiken gibt es ohne Protokollierung?', 5, '[{"text": "Unklare Fehler", "correct": true, "because": "Keine Nachverfolgung"}, {"text": "Schwerere Diagnose", "correct": true, "because": "Fehlende Infos"}, {"text": "Schnellere Systeme", "correct": false, "because": "Kein Risiko"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Protokollierung unwichtig?', 3, '[{"text": "Fehlerkontext", "correct": false, "because": "Hilft bei Analyse"}, {"text": "Code", "correct": false, "because": "Identifiziert Problem"}, {"text": "Serverdesign", "correct": true, "because": "Kein direkter Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Müssen Meldungen immer technisch sein?', 3, '[{"text": "Nein", "correct": true, "because": "Können nutzerfreundlich sein"}, {"text": "Ja", "correct": false, "because": "Flexibel gestaltbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Protokollierung automatisch ist?', 2, '[{"text": "Nein", "correct": true, "because": "Muss implementiert werden"}, {"text": "Ja", "correct": false, "because": "Entwicklerabhängig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Level wähle ich für schwerwiegende Fehler?', 4, '[{"text": "ERROR", "correct": true, "because": "Markiert kritische Probleme"}, {"text": "INFO", "correct": false, "because": "Nur Informationen"}, {"text": "DEBUG", "correct": false, "because": "Entwicklungsdetails"}]');
